INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2562154, 354211, 35602, '<td valign="top">Maybe not, but this one looks absolutely evil.  Great capture.  Red eye would have really worked well on this one.</td>', 'Maybe not, but this one looks absolutely evil.  Great capture.  Red eye would have really worked well on this one.', '2006-06-28 13:32:21.000000', NULL, 1),
(2562157, 354158, 35602, '<td valign="top">Seems way underexposed.  Even though the background would have been whited out, if you had compensated exposure by +1 or so, the toad would have come out much better.</td>', 'Seems way underexposed.  Even though the background would have been whited out, if you had compensated exposure by +1 or so, the toad would have come out much better.', '2006-06-28 13:33:58.000000', NULL, 1),
(2562159, 354115, 60223, '<td valign="top">With his hands on the steering wheel I would assume that he is driving which makes the harsh lighting coming from above seem very out of place.  Maybe if it had been lit from straight on or from the rear as if by headlights it would match better.</td>', 'With his hands on the steering wheel I would assume that he is driving which makes the harsh lighting coming from above seem very out of place.  Maybe if it had been lit from straight on or from the rear as if by headlights it would match better.', '2006-06-28 13:34:45.000000', NULL, 1),
(2562161, 351674, 35602, '<td valign="top">Have you ever eaten squirrel?  I have a great recipe from the 30''s on how to cook them.  One way is fried.  No, I have not tried it.  Just wanted to gross you out.</td>', 'Have you ever eaten squirrel?  I have a great recipe from the 30''s on how to cook them.  One way is fried.  No, I have not tried it.  Just wanted to gross you out.', '2006-06-28 13:35:25.000000', NULL, 1),
