(2570910, 353216, 60223, '<td valign="top">Excellent photo.  Nice framing all around.  Too bad the save for web was not kind to the edge of her hand (which I will not vote you down for of course).</td>', 'Excellent photo.  Nice framing all around.  Too bad the save for web was not kind to the edge of her hand (which I will not vote you down for of course).', '2006-06-30 22:29:11.000000', NULL, 1),
(2570913, 354674, 60223, '<td valign="top">I find this one very funny, I think it''s the brightness of the photo in an otherwise terrifying moment.</td>', 'I find this one very funny, I think it''s the brightness of the photo in an otherwise terrifying moment.', '2006-06-30 22:30:18.000000', NULL, 1),
