(2570972, 353419, 29490, '<td valign="top">Good lord! :)</td>', 'Good lord! :)', '2006-06-30 22:54:04.000000', NULL, 1),
(2571017, 354688, 29490, '<td valign="top">I like.  I don''t know but you might be getting flack for the underexposed face of CloserKitty - I think it works wonders with only the eyes visible, it leads nicely with the eye-filled dealybob hanging on the wall.</td>', 'I like.  I don''t know but you might be getting flack for the underexposed face of CloserKitty - I think it works wonders with only the eyes visible, it leads nicely with the eye-filled dealybob hanging on the wall.', '2006-06-30 23:05:36.000000', NULL, 1),
