(2571195, 354411, 18799, '<td valign="top">I don''t understand the superstition or the urban legend here.  Feel free to pm and explain.  Image is too small - you''ll get voted down for this.</td>', 'I don''t understand the superstition or the urban legend here.  Feel free to pm and explain.  Image is too small - you''ll get voted down for this.', '2006-07-01 00:10:22.000000', NULL, 1),
(2571207, 354676, 35530, '<td valign="top">Love the DOF in this. Would have made a great Bokeh entry. The only thing different I would have liked would be to have your model slightly off center. Still a beautiful shot.</td>', 'Love the DOF in this. Would have made a great Bokeh entry. The only thing different I would have liked would be to have your model slightly off center. Still a beautiful shot.', '2006-07-01 00:13:26.000000', NULL, 1),
(2571219, 354598, 35530, '<td valign="top">Almost forgot about that one. Great clarity and color. The tilt of the Coke can really makes this.</td>', 'Almost forgot about that one. Great clarity and color. The tilt of the Coke can really makes this.', '2006-07-01 00:15:25.000000', NULL, 1),
(2571228, 353571, 35530, '<td valign="top">One word...GREAT!</td>', 'One word...GREAT!', '2006-07-01 00:17:44.000000', NULL, 1),
(2571233, 354748, 35530, '<td valign="top">Best lightning shot of the bunch. Very nice capture.</td>', 'Best lightning shot of the bunch. Very nice capture.', '2006-07-01 00:19:02.000000', NULL, 1),
(2571249, 353995, 35530, '<td valign="top">Great idea. I like how the shards of glass are flying off the mirror. Overall, the picture seems a little overprocessed.</td>', 'Great idea. I like how the shards of glass are flying off the mirror. Overall, the picture seems a little overprocessed.', '2006-07-01 00:25:52.000000', NULL, 1),
